// Bounded real Windows mouse gesture, only in the identified local laboratory noVNC window.
using System;using System.Diagnostics;using System.Linq;using System.Windows.Automation;using System.Runtime.InteropServices;using System.Threading;using System.Text;
class BrowserMouse {
 [DllImport("user32.dll")] static extern bool SetProcessDPIAware();
 [DllImport("user32.dll")] static extern bool SetForegroundWindow(IntPtr h);
 [DllImport("user32.dll")] static extern IntPtr GetForegroundWindow();
 [DllImport("user32.dll")] static extern bool SetCursorPos(int x,int y);
 [DllImport("user32.dll")] static extern void mouse_event(uint flags,uint dx,uint dy,uint data,UIntPtr extra);
 static void Main(string[] args){SetProcessDPIAware();Console.OutputEncoding=Encoding.UTF8;if(args.Length!=1||(args[0]!="drag-left"&&args[0]!="drag-right"))throw new Exception("Only one bounded page gesture allowed");var p=Process.GetProcessesByName("brave").Single(x=>x.MainWindowHandle!=IntPtr.Zero&&x.MainWindowTitle.StartsWith("Hyundai i20 N"));var root=AutomationElement.FromHandle(p.MainWindowHandle);var doc=root.FindFirst(TreeScope.Descendants,new AndCondition(new PropertyCondition(AutomationElement.ControlTypeProperty,ControlType.Document),new PropertyCondition(AutomationElement.NameProperty,"QEMU (I20N LAB - home EXPERIMENTAL) - noVNC")));if(doc==null)throw new Exception("Identified noVNC document absent");var r=doc.Current.BoundingRectangle;if(r.IsEmpty||r.Width<1000||r.Height<700)throw new Exception("Unexpected viewport");SetForegroundWindow(p.MainWindowHandle);doc.SetFocus();Thread.Sleep(500);if(GetForegroundWindow()!=p.MainWindowHandle)throw new Exception("Lab browser is not foreground; no mouse input");double scale=Math.Min(r.Width/1280.0,r.Height/800.0),left=r.Left+(r.Width-1280*scale)/2,top=r.Top+(r.Height-800*scale)/2;int from=args[0]=="drag-left"?1120:160,to=args[0]=="drag-left"?160:1120,y=(int)Math.Round(top+660*scale);SetCursorPos((int)Math.Round(left+from*scale),y);Thread.Sleep(500);try{mouse_event(2,0,0,0,UIntPtr.Zero);Thread.Sleep(200);for(int i=1;i<=12;i++){if(GetForegroundWindow()!=p.MainWindowHandle)throw new Exception("Foreground changed");SetCursorPos((int)Math.Round(left+(from+(to-from)*i/12.0)*scale),y);Thread.Sleep(60);}}finally{mouse_event(4,0,0,0,UIntPtr.Zero);}Console.WriteLine("{\"action\":\""+args[0]+"\",\"transport\":\"Windows user32 mouse -> Brave -> noVNC -> QEMU\",\"browser_pid\":"+p.Id+",\"scale\":"+scale.ToString(System.Globalization.CultureInfo.InvariantCulture)+",\"utc\":\""+DateTime.UtcNow.ToString("o")+"\"}");}
}
